        dest[destOffset + 2] = 0.0;
        dest[destOffset + 3] = 0.0;
        dest[destOffset + 4] = 0.0;
        dest[destOffset + 5] = 1.0;
        dest[destOffset + 6] = 0.0;
        dest[destOffset + 7] = 0.0;
