    public static long mulVec4(long dest, long src, double vX, double vY, double vZ, double vW) {
        if (Joml.storeLoadBackend() == StoreLoadBackend.UNSAFE) return Double4x4OpsKernelsAddress.mulVec4_unsafe(dest, src, vX, vY, vZ, vW);
        mulVec4(VirtualMemoryHolder.virtualMemory().asSlice(dest, 32L), 0L, VirtualMemoryHolder.virtualMemory().asSlice(src, 128L), 0L, vX, vY, vZ, vW);
        return dest;
    }

